<?php
namespace Tests\Feature;
use App\Livewire\LMS\QuizQuestions\Index; use App\Models\{AcademicYear,ClassSubject,Question,Quiz,School,SchoolClass,Subject,Teacher,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Livewire\Livewire; use Spatie\Permission\Models\Role; use Tests\TestCase;
class QuizQuestionCrudTest extends TestCase { use RefreshDatabase; public function test_school_admin_can_add_a_banked_question_to_a_quiz():void { Role::create(['name'=>'school_admin']);$user=User::factory()->create();$user->assignRole('school_admin');$school=School::create(['name'=>'BrightStar Academy','code'=>'BSA']);$year=AcademicYear::create(['school_id'=>$school->id,'name'=>'2026/2027','starts_at'=>'2026-09-01','ends_at'=>'2027-07-31']);$class=SchoolClass::create(['academic_year_id'=>$year->id,'name'=>'Basic 4']);$subject=Subject::create(['school_id'=>$school->id,'name'=>'Mathematics','code'=>'MATH']);$teacher=Teacher::create(['school_id'=>$school->id,'employee_id'=>'T-001','first_name'=>'Ama','last_name'=>'Mensah']);$quiz=Quiz::create(['class_subject_id'=>ClassSubject::create(['school_class_id'=>$class->id,'subject_id'=>$subject->id,'teacher_id'=>$teacher->id])->id,'teacher_id'=>$teacher->id,'title'=>'Fractions Quiz','max_attempts'=>1]);$question=Question::create(['school_id'=>$school->id,'created_by'=>$user->id,'type'=>'short_answer','prompt'=>'What is half of ten?','grading_key'=>['answer'=>'5'],'max_score'=>1]);Livewire::actingAs($user)->test(Index::class,['quiz'=>$quiz])->call('create')->set('questionId',(string)$question->id)->set('sequence','1')->call('save')->assertHasNoErrors();$this->assertDatabaseHas('quiz_questions',['quiz_id'=>$quiz->id,'question_id'=>$question->id,'sequence'=>1]);} }
